Method.Source:
    // MPJ-21310

    /// <summary>
    /// Check if this entry is already referenced on a sales order line.
    /// </summary>
    /// <returns>Result</returns>
    public boolean salesLineExists()
    {
        METSalesLine   metSalesLine;
        select firstonly metSalesLine
            where   metSalesLine.SubstitutionType           == METSalesItemSubstitutionType::ParentChild
            &&      metSalesLine.SubstitutionSetupRefRecID  == this.RecId;
        return metSalesLine.RecID != 0;
    }

/// <summary>
/// validateWrite
/// </summary>
/// <returns>Result</returns>
public boolean validateWrite()
{
    boolean ret;

    ret = super();

    if(ret)
    {
        METSalesItemSubstitutionParentChild otherParentChild;
        select firstonly otherParentChild
            where   otherParentChild.ParentItemID   == this.ChildItemID
            &&      otherParentChild.InventSiteId   == this.InventSiteId
            &&      otherParentChild.RecId          != 0;
        if(otherParentChild)
        {
            ret = checkFailed(strFmt("Can't set %1 up as a child item because it has already been specified as a parent item on another record",
                this.ChildItemID));
        }
        select firstonly otherParentChild
            where   otherParentChild.ChildItemID    == this.ParentItemID
            &&      otherParentChild.InventSiteId   == this.InventSiteId
            &&      otherParentChild.RecId          != 0;
        if(otherParentChild)
        {
            ret = checkFailed(strFmt("Can't set %1 up as a parent item because it has already been specified as a child item on another record",
                this.ParentItemID));
        }
    }
    return ret;
}
